let lang = 'en';

export function detectLang() {
  const prefs = (typeof navigator !== 'undefined' && (navigator.languages || [navigator.language])) || [];
  for (const p of prefs) { const code = String(p).slice(0, 2).toLowerCase(); if (code in dict) return code; }
  return 'en';
}

export function setLang(code) {
  lang = code in dict ? code : detectLang();
  if (typeof document !== 'undefined') document.documentElement.lang = lang;
}
export function getLang() { return lang; }

const reported = new Set();
export function t(key, ...args) {
  const v = dict[lang][key] ?? dict.en[key];
  if (v === undefined) {
    // A missing translation shows its key; say so once (the tests fail on console errors).
    if (!reported.has(key) && typeof console !== 'undefined') { reported.add(key); console.error(`i18n: missing key "${key}"`); }
    return key;
  }
  return typeof v === 'function' ? v(...args) : v;
}

export const _dict = dict; // for tests
